diff --git a/bin/fah.dart b/bin/fah.dart
index 1ae874668..13fa825a4 100644
--- a/bin/fah.dart
+++ b/bin/fah.dart
@@ -64,6 +64,7 @@ import 'self_manage.dart';
 import 'serve_a2a.dart';
 import 'serve_bridge.dart';
 import 'fah_boot_restore.dart';
+import 'fah_herdr_spawn.dart';
 import 'fah_wire_serve.dart';
 import 'package:flutter_agent_harness/src/cli/provider_export.dart';

diff --git a/bin/fah_runapp.dart b/bin/fah_runapp.dart
index 1de64a345..cd6d6d9a6 100644
--- a/bin/fah_runapp.dart
+++ b/bin/fah_runapp.dart
@@ -1320,6 +1320,19 @@ Future<void> _runApp(List<String> args) async {
           if (value != null && value.isNotEmpty) return value;
           return keyCache.read(name);
         },
+        // herdr pane self-report (issue #1481): the gate reads the pane env
+        // herdr exports to every pane process; each report spawns the pane's
+        // herdr binary fire-and-forget (reporter-side short timeout, silent
+        // on failure). Outside herdr the reporter is inert.
+        herdrEnvLookup: (name) => Platform.environment[name],
+        // Kill-on-timeout with drained stdio (bin/fah_herdr_spawn.dart,
+        // unit-pinned by test/bin_herdr_spawn_drain_test.dart): the
+        // reporter abandons a slow report (2s, silent), but the subprocess
+        // must not linger — it is killed inside the kill window so a
+        // wedged herdr can't leak one process per state transition, and
+        // its stdout/stderr are drained so a chatty herdr can't block on
+        // a full pipe until that window.
+        herdrSpawn: spawnHerdrReport,
         // `/key` manages the platform secure store; `/provider ... <token>`
         // persists the token there.
         secureKeys: keyCache,
diff --git a/lib/src/cli/agent_cli_config.dart b/lib/src/cli/agent_cli_config.dart
index b36658502..01bff6835 100644
--- a/lib/src/cli/agent_cli_config.dart
+++ b/lib/src/cli/agent_cli_config.dart
@@ -37,6 +37,8 @@ final class AgentCliConfig {
     this.providerKind = 'openai-completions',
     this.envVarIsSet,
     this.envVarValue,
+    this.herdrEnvLookup,
+    this.herdrSpawn,
     this.modelsFetcher,
     this.modelsHttpClient,
     this.tuiMouseCapture = true,
@@ -735,6 +737,23 @@ final class AgentCliConfig {
   /// (tests, web) means no key is ever found this way.
   final String? Function(String name)? envVarValue;

+  /// Reads a herdr pane env var on the host (issue #1481): the herdr pane
+  /// reporter's whole gate input (`HERDR_ENV`, `HERDR_PANE_ID`,
+  /// `HERDR_BIN_PATH`, plus the `FA_HERDR=0` kill switch). herdr exports
+  /// the vars to every pane process, so the CLI's own process env is the
+  /// right source. Null (tests, web) = every var unset — the reporter is
+  /// constructed inert and spawns nothing. lib/src stays dart:io-free; the
+  /// executable injects the `Platform.environment` lookup.
+  final String? Function(String name)? herdrEnvLookup;
+
+  /// The herdr pane reporter's transport (issue #1481): one fire-and-forget
+  /// spawn of `$HERDR_BIN_PATH pane …` per report, cut by the reporter's
+  /// short timeout, silent on failure. The executable injects a
+  /// `Process.run`-backed closure (lib/ stays dart:io-free); null (tests
+  /// without a recorder, web) keeps the reporter spawn-free even behind an
+  /// active gate.
+  final Future<void> Function(List<String> argv)? herdrSpawn;
+
   /// Fetches model ids from an OpenAI-compatible `/models` endpoint (the
   /// `/models` picker and the custom-provider flow). Null uses the built-in
   /// HTTP implementation; tests inject a fake.
diff --git a/lib/src/cli/provider_commands.dart b/lib/src/cli/provider_commands.dart
index ae02a9d54..e30fb42fa 100644
--- a/lib/src/cli/provider_commands.dart
+++ b/lib/src/cli/provider_commands.dart
@@ -2444,7 +2444,7 @@ extension on AgentCli {
       name: name,
       keys: keys,
       onSecretStored: config.onSecretStored,
-      prompt: tui.openPrompt,
+      prompt: (spec) => _openHerdrPrompt(tui, spec),
       onResult: io.writeln,
       onSaved: _applySavedKeyToActiveProvider,
     );
diff --git a/lib/src/cli/provider_flow_helpers.dart b/lib/src/cli/provider_flow_helpers.dart
index d9e3fbea2..2535a9b05 100644
--- a/lib/src/cli/provider_flow_helpers.dart
+++ b/lib/src/cli/provider_flow_helpers.dart
@@ -26,7 +26,7 @@ extension on AgentCli {
       defaultValue: _extractDefault(question),
       secret: [REDACTED:Sensitive Value],
     );
-    final result = await tui.openPrompt(spec);
+    final result = await _openHerdrPrompt(tui, spec);
     return result is TextPromptAnswer ? result.value : null;
   }

diff --git a/lib/src/cli/provider_models.dart b/lib/src/cli/provider_models.dart
index cfe5d5f96..334d9337c 100644
--- a/lib/src/cli/provider_models.dart
+++ b/lib/src/cli/provider_models.dart
@@ -1334,7 +1334,7 @@ extension on AgentCli {
   /// with the live controller + model.
   Future<void> _modelEditInteractive() => interactiveModelEdit(
