```dart
Future<ProcessResult> _runWithStdin(executable, args, stdinText, {Duration timeout = _timeout}) async {
  final process = await Process.start(executable, args);
  process.stdin.write(stdinText);
  await process.stdin.flush();
  await process.stdin.close();
  try {
    await process.stderr.drain<void>().timeout(timeout);
    await process.stdout.drain<void>().timeout(timeout);
    final exitCode = await process.exitCode.timeout(timeout);
    return ProcessResult(process.pid, exitCode, null, null);
