  Future<void> runWithEnv(ExecutionEnv env) async {
    bootWindow();
    kBootWatchdog.install();
    BootSteps.mark('window');
    await bootServices();
    BootSteps.mark('services');
    return _runStages(env);
  }

  Future<void> _runStages(ExecutionEnv env) async {
    debugPrint(
