  /// (default `copilot-<login>`), pick the plan (base URL), store the
  /// token under the entry-scoped key, register, and switch.
  Future<void> _applyCopilotCredentials(String githubToken) async {
    final spec = providerCatalog['copilot']!;
    final String login;
    try {
      login = await (config.copilotUserFn ?? _defaultCopilotUser)(githubToken);
    } on Object catch (error) {
      io.writeln('could not resolve the GitHub account: $error');
      return;
    }

    // The default entry name IS the account identity: re-running the flow
    // for the same login reuses that entry (and its key slot), so only
    // that account's token is renewed.
    final fallback = 'copilot-$login';
    // An existing COPILOT entry under the same name is the re-auth target,
    // not a clash (the plan — and so the URL — isn't known yet).
    final name =
        await _askConnectProviderName(
          fallback,
          allowClash: (entry) => entry.apiType == 'copilot',
        ) ??
        fallback;

    final baseUrl = await _copilotAskAccountType();
    if (baseUrl == null) {
      io.writeln('Copilot connect cancelled');
      return;
    }

    final registry = config.customProviders;
    final keyName =
        registry?.find(name)?.keyName ??
        CustomProviderRegistry.copilotEntryKeyName(name);
    await _storeProviderToken(spec, baseUrl, githubToken, keyName: keyName);
    // Surface the token-exchange failure NOW: the /models dialect below
    // swallows errors into an empty list, which would drop the user into
    // manual model entry with no hint why (fine-grained PAT, no Copilot
    // plan on the account, dead network — live finding 2026-09). One
    // cheap GET; the model fetch exchanges again. A fine-grained PAT
    // skips this entirely (PAT mode): GitHub 404s every PAT exchange,
    // and the /models fetch below validates it against the Copilot API
    // directly.
    if (!isFineGrainedGitHubPat(githubToken)) {
      try {
        await fetchCopilotApiToken(
          githubToken: githubToken,
          client: config.modelsHttpClient,
        );
      } on CopilotAuthException catch (error) {
        io.writeln('warning: ${error.message}');
        io.writeln('continuing — pick or type the model id manually');
      }
    }
    // No provider carries a default model — the id comes from the live
    // /models list (user picks) or a manual entry.
    final ids = await _fetchProviderModelIds(spec.name, baseUrl, githubToken);
    if (isFineGrainedGitHubPat(githubToken) && ids.isEmpty) {
      // PAT mode validates against the Copilot API HERE (no exchange):
      // an empty answer means the PAT was rejected or grants nothing —
      // name the likely causes instead of a silent manual-entry drop.
      io.writeln(
        'note: the Copilot API returned no models for this PAT — check '
        'the "Copilot Requests" permission '
        '(github.com/settings/personal-access-tokens → edit → '
        'Permissions) and the account\'s Copilot seat',
      );
    }
    final picked = ids.isNotEmpty
        ? await _pickModelFromList(ids, title: 'Copilot model')
        : await _manualModelId();
    if (picked == null) {
      io.writeln('Copilot connect cancelled');
      return;
    }
    registry?.add(
      CustomProviderEntry(
        name: name,
        apiType: 'copilot',
        baseUrl: baseUrl,
        modelId: picked,
        keyName: keyName,
      ),
    );
    _activeCustomName = name;
    io.writeln('saved provider \$name (listed in /provider)');
    await _switchProvider(
      spec,
      baseUrl,
      picked,
      token: [REDACTED:Sensitive Value],
      tokenKeyName: keyName,
    );
  }

