/// The host-side Copilot CLI identity install for the Flutter app
/// (gh-1606 review): the app is a second first-class PAT surface (the
/// connect sheet pastes tokens; the chat runtime streams through the
/// harness), so its boot installs the PAT-mode user-agent identity the
/// same way the CLI host does — app-side PAT requests then present
/// `copilot/<version> (<os>) term/unknown` instead of the
/// keep-working default `copilot/fa (unknown)`.
///
/// Conditional import: the OS slot needs `dart:io` on IO hosts; web
/// builds install the honest `'web'` value instead.
export 'copilot_cli_identity_stub.dart'
    if (dart.library.io) 'copilot_cli_identity_io.dart';
","path":"flutter_app/lib/services/copilot_cli_identity.dart"}

{"content":"// Copyright (c) 2026, the Flutter Agent Harness authors.
// Use of this source code is governed by a MIT license that can be found
// in the LICENSE file.

/// Web build of the app-side Copilot CLI identity install: `dart:io` is
/// unavailable, so the OS slot carries the honest `'web'` value (the
/// browser build still streams provider requests through the harness).
library;

import 'package:flutter_agent_harness/flutter_agent_harness.dart';

/// The app's version for the Copilot PAT-mode user-agent: the build name
/// flutter bakes as a dart-define (`--build-name`, or the pubspec version
/// in dev runs); `'fa'` keeps requests working when neither is set.
const faAppVersion = String.fromEnvironment(
  'FLUTTER_BUILD_NAME',
  defaultValue: 'fa',
);

/// Installs the identity at app boot (see the barrel doc).
void installHostCopilotCliIdentity() {
  installCopilotCliIdentity(version: faAppVersion, os: 'web');
}
