{"command":"python3 - <<'EOF'
import re, collections
def parse(path):
    files = collections.OrderedDict()
    cur = None
    for line in open(path):
        line = line.strip()
        if line.startswith('SF:'):
            cur = files.setdefault(line[3:], {'da': {}, 'brda': {}, 'fn': {}})
        elif line.startswith('DA:') and cur is not None:
            ln, cnt = line[3:].split(',')[:2]
            ln = int(ln); cnt = int(cnt)
            cur['da'][ln] = max(cur['da'].get(ln, 0), cnt)
        elif line.startswith('BRDA:') and cur is not None:
            parts = line[5:].split(',')
            key = (parts[0], parts[1], parts[2], parts[3])
            cur['brda'][key] = parts[3]
        elif line.startswith('end_record'):
            cur = None
    return files
a = parse('/tmp/cov-full/lcov.info')
b = parse('/tmp/cov-jsr/lcov.info')
out = open('/tmp/cov-merged/merged.info', 'w')
for sf in dict(a, **{k: a.get(k) or v for k, v in b.items()}):
    rec = b.get(sf) or a[sf]
    if sf in a and sf in b:
        rec = {'da': dict(a[sf]['da']), 'brda': dict(a[sf]['brda'])}
        for ln, cnt in b[sf]['da'].items():
            rec['da'][ln] = max(rec['da'].get(ln, 0), cnt)
        rec['brda'].update(b[sf]['brda'])
    out.write(f'SF:{sf}\n')
    for (ln, block, branch, taken) in sorted(rec['brda']):
        out.write(f'BRDA:{ln},{block},{branch},{taken}\n')
    for ln in sorted(rec['da']):
        out.write(f'DA:{ln},{rec["da"][ln]}\n')
    lf = len(rec['da']); lh = sum(1 for c in rec['da'].values() if c > 0)
    out.write(f'LF:{lf}\nLH:{lh}\nend_record\n')
out.close()
print('merged files:', len(set(a) | set(b)))
EOF"}

